-- Seed for fixtures/SalesPostgres (run as a superuser on a throwaway database named analytics).
CREATE SCHEMA IF NOT EXISTS sales; CREATE SCHEMA IF NOT EXISTS ref; CREATE SCHEMA IF NOT EXISTS planning;
CREATE TABLE ref.regions (region_code text PRIMARY KEY, region_name text NOT NULL, sort_order int);
CREATE TABLE sales.customer (customer_id int PRIMARY KEY, customer_name text, segment text, country text, email text, phone text, is_active boolean);
CREATE TABLE sales.orders (order_id int PRIMARY KEY, order_date date, customer_id int, region text, region_code text, amount numeric(12,2), status text);
CREATE TABLE planning."MonthlyTargets" ("Region" text, target_month date, target_amount numeric(12,2), fiscal_year int);
